def countOppositeParity(nums: list[int]) -> list[int]:
    cnt = [0, 0]
    for x in nums:
        cnt[x % 2] += 1
    ans = []
    for x in nums:
        p = x % 2
        cnt[p] -= 1
        ans.append(cnt[1 - p])
    return ans

#include <vector>

class Solution {
public:
    std::vector<int> countOppositeParity(std::vector<int>& nums) {
        int cnt[2] = {0, 0};
        for (int x : nums) cnt[x % 2]++;
        std::vector<int> ans;
        for (int x : nums) {
            int p = x % 2;
            cnt[p]--;
            ans.push_back(cnt[1 - p]);
        }
        return ans;
    }
};

class Solution {
    public int[] countOppositeParity(int[] nums) {
        int[] cnt = new int[2];
        for (int x : nums) cnt[x % 2]++;
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int p = nums[i] % 2;
            cnt[p]--;
            ans[i] = cnt[1 - p];
        }
        return ans;
    }
}

